select ord_codigo, proder_codigo, prod_nome||coalesce(' - '||proder_nome,'') as prod_nome
  from compras.cp_ordem_compra 
  join compras.cp_ordem_compra_item 
 using (ord_id)
  join mz_produto_derivacao mpd 
 using (proder_id) 
  join mz_produto 
 using (prod_id)
 where ord_codigo  = :ordem
